/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	var roles = api.context.session.user.roles;
	var role = roles.join(',');
	if (roles.includes('sn_cmdb_admin') || roles.includes('admin') || roles.includes('maint')) {
		role = 'sn_cmdb_admin';
	} else if (roles.includes('sn_cmdb_editor')) {
		role = 'sn_cmdb_editor';
	} else if (roles.includes('sn_cmdb_user')) {
		role = 'sn_cmdb_user';
	}
	return {
		event: 'Explore CI: Form Opened',
		value: {'class': api.context.props.table, 'role': role}
	};
}
